def _found(text: str, etype: str, value: str) -> bool:
    return any(e.type == etype and e.slice(text) == value for e in detect(text))
 
 
def measure_recall(n: int, seed: int) -> list[dict]:
    rows = []
    for etype, style, make, template in POSITIVES:
        rng = random.Random(f"{seed}:{etype}:{style}")
        k = 0
        for _ in range(n):
            value = make(rng)
            k += _found(template.format(value), etype, value)
        lo, hi = wilson(k, n)
        rows.append({"type": etype, "style": style, "n": n, "found": k, "rate": k / n, "ci_low": lo, "ci_high": hi})
    return rows
 
 
def _random_alnum_code(rng: random.Random, valid_holder: bool) -> str:
    fourth = rng.choice("ABCFGHLJPT") if valid_holder else rng.choice("DEIKMNOQRSUVWXYZ")
    return "".join(rng.choice(string.ascii_uppercase) for _ in range(3)) + fourth + rng.choice(string.ascii_uppercase) \
        + synth.random_digits(rng, 4) + rng.choice(string.ascii_uppercase)
 
 
def _clean_sentence(rng: random.Random) -> str:
    return rng.choice([
        lambda: f"The invoice total is {rng.randint(100, 99999):,} rupees for {rng.randint(1, 9)} items.",
        lambda: f"Meeting at {rng.randint(1, 12)}:{rng.randint(10, 59)} on {rng.randint(1, 28):02d}.{rng.randint(1, 12):02d}.2026.",
        lambda: f"Deliver to pincode {rng.randint(110001, 855117)}, floor {rng.randint(1, 20)}.",
        lambda: f"Flight AI{rng.randint(100, 999)} departs from gate {rng.randint(1, 60)}.",
        lambda: f"Please explain how UPI works and why my loan {rng.randint(1000, 9999)} was rejected.",
        lambda: f"Rs {rng.randint(10, 9999)}.{rng.randint(10, 99)} was debited on {rng.randint(1, 28)} March.",
        lambda: f"Reference {synth.random_digits(rng, 8)} has been updated.",
        lambda: f"Page {rng.randint(1, 300)} of {rng.randint(300, 900)}; section {rng.randint(1, 20)}.{rng.randint(1, 20)}.",
    ])()
 
 
# (case, entity types that count as a false positive, sample maker, note)
# A note marks cases where the text is indistinguishable from a real identifier by format alone.
NEGATIVES = [
    ("clean sentences (amounts, dates, pincodes, flight no.)", ["AADHAAR", "PAN", "MOBILE", "UPI", "GSTIN", "IFSC", "CARD", "BANK_ACCOUNT", "OTP", "CVV", "EMAIL"],
     lambda r: _clean_sentence(r), ""),
    ("order/invoice number shaped like an Aadhaar", ["AADHAAR"],
     lambda r: f"order id {synth.aadhaar(r)} has shipped", ""),
    ("random 12-digit number, no context", ["AADHAAR"],
     lambda r: f"value {synth.random_12_digit(r)} end",
     "about 1 in 10 random numbers passes the Aadhaar checksum"),
    ("random 10-digit number starting 6-9, no context", ["MOBILE"],
     lambda r: f"value {synth.mobile(r)} end",
     "unavoidable: identical in format to a real mobile number; it is only masked, not blocked"),
    ("random 16-digit number that fails Luhn", ["AADHAAR", "MOBILE", "CARD", "BANK_ACCOUNT"],
     lambda r: f"reference {synth.group(_non_luhn_16(r))} noted", ""),
    ("PAN-shaped code with an invalid holder letter", ["PAN"],
     lambda r: f"code {_random_alnum_code(r, valid_holder=False)} here", ""),
    ("PAN-shaped code with a valid holder letter", ["PAN"],
     lambda r: f"code {_random_alnum_code(r, valid_holder=True)} here",
     "unavoidable: identical in format to a real PAN"),
]
 
 
def _non_luhn_16(rng: random.Random) -> str:
    while True:
        s = rng.choice("23456789") + synth.random_digits(rng, 15)
        if _luhn_check(s) is False:
            return s
 
 
def _luhn_check(s: str) -> bool:
    from .detectors import luhn_valid
    return luhn_valid(s)
 
 
def measure_false_positives(n: int, seed: int) -> list[dict]:
    rows = []
    for label, watch, make, note in NEGATIVES:
        rng = random.Random(f"{seed}:neg:{label}")
        k, fired = 0, {}
        for _ in range(n):
            hits = [e.type for e in detect(make(rng)) if e.type in watch]
            if hits:
                k += 1
                for t in set(hits):
                    fired[t] = fired.get(t, 0) + 1
        lo, hi = wilson(k, n)
        rows.append({"case": label, "n": n, "flagged": k, "rate": k / n, "ci_low": lo, "ci_high": hi, "fired": fired, "note": note})
    return rows
 
 
def measure_leak_through(n: int, seed: int) -> list[dict]:
    """With the default policy applied, how often does the raw value still reach the LLM?"""
    by_type: dict[str, list] = {}
    for etype, style, make, template in POSITIVES:
        by_type.setdefault(etype, []).append((make, template))
    rows = []
    for etype, variants in by_type.items():
        rng = random.Random(f"{seed}:leak:{etype}")
        allowed_by_policy = Policy.default().rule_for(etype).action is Action.ALLOW
        leaked = blocked = protected = allowed = 0
        for _ in range(n):
            make, template = rng.choice(variants)
            value = make(rng)
            r = protect(template.format(value), "eval", TokenVault())
            if r.blocked:
                blocked += 1
            elif _canon(value) in _canon(r.text):
                if allowed_by_policy:
                    allowed += 1
                else:
                    leaked += 1
            else:
                protected += 1
        lo, hi = wilson(leaked, n)
        rows.append({"type": etype, "n": n, "leaked": leaked, "blocked": blocked, "protected": protected,
                     "allowed_by_policy": allowed,
                     "leak_rate": leaked / n, "ci_low": lo, "ci_high": hi})
    return rows
 
 
def measure_latency(n: int, seed: int) -> dict:
    rng = random.Random(f"{seed}:latency")
    messages = []
    for _ in range(n):
        if rng.random() < 0.5:
            _, _, make, template = rng.choice(POSITIVES)
            messages.append(template.format(make(rng)))
        else:
            messages.append(_clean_sentence(rng))
    vault = TokenVault()
    protect_ms, scan_ms = [], []
    for m in messages:
        t0 = time.perf_counter()
        protect(m, "lat", vault)
        protect_ms.append((time.perf_counter() - t0) * 1000)
        t0 = time.perf_counter()
        scan_and_restore(m, "lat", vault)
        scan_ms.append((time.perf_counter() - t0) * 1000)
 
    def summ(xs):
        xs = sorted(xs)
        return {"p50_ms": round(statistics.median(xs), 3), "p95_ms": round(xs[int(0.95 * (len(xs) - 1))], 3),
                "max_ms": round(xs[-1], 3)}
    return {"messages": n, "protect": summ(protect_ms), "reply_scan": summ(scan_ms)}
 
 
def run(n: int = 500, seed: int = SEED) -> dict:
    attacks = [{"title": s.title, "no_gateway": d, "gateway": g} for s, d, g in run_attacks()]
    return {
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "seed": seed,
        "n_per_row": n,
        "recall": measure_recall(n, seed),
        "false_positives": measure_false_positives(n, seed),
        "leak_through": measure_leak_through(n, seed),
        "latency": measure_latency(min(n, 500), seed),
        "attacks": attacks,
        "caveats": CAVEATS,
    }
 
 
def _pct(x: float) -> str:
    return f"{100 * x:5.1f}%"
 
 
def print_report(res: dict) -> None:
    print(f"Evaluation (seed {res['seed']}, n={res['n_per_row']} per row). Synthetic data; see caveats at the end.\n")
    print("RECALL: identifier found with the exact span")
    print(f"  {'type':<13}{'writing style':<32}{'found':>9}{'rate':>9}   95% CI")
    for r in res["recall"]:
        print(f"  {r['type']:<13}{r['style']:<32}{r['found']:>4}/{r['n']:<4}{_pct(r['rate'])}   {_pct(r['ci_low'])} - {_pct(r['ci_high']).strip()}")
    print("\nFALSE POSITIVES: harmless text wrongly flagged")
    print(f"  {'case':<55}{'flagged':>9}{'rate':>9}   95% CI")
    for r in res["false_positives"]:
        print(f"  {r['case']:<55}{r['flagged']:>4}/{r['n']:<4}{_pct(r['rate'])}   {_pct(r['ci_low'])} - {_pct(r['ci_high']).strip()}"
              + (f"   * {r['note']}" if r["note"] else ""))
    print("\nLEAK-THROUGH: raw value still reaches the LLM (default policy)")
    print(f"  {'type':<13}{'leaked':>8}{'blocked':>9}{'tokenized/masked':>18}{'allowed by policy':>19}{'leak rate':>11}")
    for r in res["leak_through"]:
        print(f"  {r['type']:<13}{r['leaked']:>8}{r['blocked']:>9}{r['protected']:>18}{r['allowed_by_policy']:>19}{_pct(r['leak_rate']):>11}")
    lat = res["latency"]
    print(f"\nLATENCY over {lat['messages']} messages (ms): "
          f"protect p50 {lat['protect']['p50_ms']} / p95 {lat['protect']['p95_ms']} / max {lat['protect']['max_ms']}; "
          f"reply scan p50 {lat['reply_scan']['p50_ms']} / p95 {lat['reply_scan']['p95_ms']} / max {lat['reply_scan']['max_ms']}")
    print("\nATTACKS (simulated bank bot)")
    for a in res["attacks"]:
        lab = lambda v: "n/a" if v is None else ("LEAKED" if v else "safe")
        print(f"  {a['title']:<76}{lab(a['no_gateway']):<8}{lab(a['gateway'])}")
    print("\nCAVEATS")
    for c in res["caveats"]:
        print(f"  - {c}")
 
 
def main() -> None:
    ap = argparse.ArgumentParser(description=(__doc__ or "Measure the PII gateway").split("\n")[0])
    ap.add_argument("--n", type=int, default=500, help="samples per row (default 500)")
    ap.add_argument("--out", default="eval_results.json")
    args = ap.parse_args()
    res = run(args.n)
    with open(args.out, "w", encoding="utf-8") as f:
        json.dump(res, f, indent=2, ensure_ascii=False)
    print_report(res)
    print(f"\nWrote {args.out}")
 
 
if __name__ == "__main__":
    main()